using System.Text.Json.Serialization;
namespace HakutaiKagami.Core.Contracts;
public enum WorksKind { Agriculture,Commerce,Workshop,Pasture,Mine,Port,TradeShip,Warship,RepairFields,RepairTown,RepairCastle,Moat,Rampart,StoneWall,Gatehouse,Tower,RepairSection }
public sealed record WorksInput(EntityId Id,EntityId Site,WorksKind Kind){[JsonIgnore(Condition=JsonIgnoreCondition.WhenWritingNull)]public CastleSection? Section{get;init;}}
public sealed record WorksOrder(WorksInput Input,EntityId Actor,EntityId Owner,long At,long Revision,long Due,long Rice,long Wood,long Coins,int Crew,int Capacity,string Consent){[JsonIgnore(Condition=JsonIgnoreCondition.WhenWritingNull)]public string? AuthorizationPolicy{get;init;}}
public sealed record ShipCare(EntityId Id,EntityId Ship,EntityId Site,EntityId Actor,long At,long Until,long Revision);
public sealed record WorksState(int Schema,string Policy,WorksOrder[] Orders,ShipCare[] Care);
public sealed record WorksSite(EntityId Site,string Basis,int Agriculture,int Commerce,int Workshop,int Pasture,int Mine,int Port);
public sealed record BuiltShip(EntityId Id,EntityId Owner,EntityId Port,WorksKind Kind,long BuiltAt,bool Maintained,long PaidMonths);
public static class PublicWorks
{
 public const string Policy="local-consented-land-capacity-funded-public-works-ships-v1";
 internal static WorksOrder[] Orders(ContractWorld w)=>w.PublicWorks?.Orders??[];
 static void Need([System.Diagnostics.CodeAnalysis.DoesNotReturnIf(false)]bool c,string why){if(!c)throw new InvalidDataException(why);}
 static bool Before(WorksOrder q,long at,long rev)=>q.At<at||q.At==at&&q.Revision<rev;
 public static bool OwnIdUsed(ContractWorld w,EntityId id)=>Orders(w).Any(q=>q.Input.Id==id)||w.PublicWorks?.Care.Any(q=>q.Id==id)==true;
 public static WorksSite Land(ContractWorld w,EntityId site){Need(MaterialMarkets.Sites(w).Contains(site),"開発対象の地域ではありません");string node=NewGameWorld.Node(site.Value);bool port=NationalRoutes.Catalog.Edges.Any(e=>e.Mode=="sea"&&(e.From==node||e.To==node));return new(site,"試作用の土地容量。実測面積・史実の産地の確定値ではない",site.Value=="site:castle"?8:site.Value=="site:kofu"?4:5,4,4,site.Value is "site:kofu" or "site:suwa"?3:0,site.Value=="site:kofu"?3:0,port?3:0);}
 public static int Capacity(ContractWorld w,EntityId site,WorksKind kind,int population=200){var p=Land(w,site);if(CastleWorks.IsFort(kind))return CastleWorks.Enabled(w)?kind==WorksKind.RepairSection?100000:2:0;return kind switch{WorksKind.RepairFields or WorksKind.RepairTown or WorksKind.RepairCastle=>RegionalWeather.Enabled(w)?100000:0,WorksKind.Agriculture=>p.Agriculture,WorksKind.Commerce=>Math.Min(p.Commerce,Math.Max(0,population/50)),WorksKind.Workshop=>Math.Min(p.Workshop,Math.Max(0,population/50)),WorksKind.Pasture=>p.Pasture,WorksKind.Mine=>p.Mine,WorksKind.Port=>p.Port,_=>p.Port>0?4:0};}
 internal static int Level(ContractWorld w,EntityId site,WorksKind kind,long at,long rev)=>Orders(w).Count(q=>q.Input.Site==site&&q.Input.Kind==kind&&q.Due<=at&&Before(q,at,rev));
 public static int Level(ContractWorld w,EntityId site,WorksKind kind)=>Level(w,site,kind,w.ElapsedSeconds,w.CommitSequence+1);
 internal static int LaborAt(ContractWorld w,EntityId site,long at,long rev)=>Orders(w).Where(q=>q.Input.Site==site&&Before(q,at,rev)&&at<q.Due).Sum(q=>q.Crew);
 internal static long LaborSeconds(ContractWorld w,EntityId site,long start,long end,long rev)=>Orders(w).Where(q=>q.Input.Site==site&&q.Revision<rev).Sum(q=>Math.Max(0,Math.Min(end,q.Due)-Math.Max(start,q.At))*q.Crew);
 internal static long WoodUsed(ContractWorld w,EntityId site,long at,long rev)=>Orders(w).Where(q=>q.Input.Site==site&&Before(q,at,rev)).Sum(q=>q.Wood);
 internal static (long At,long Revision,long Amount)[] RiceTransfers(ContractWorld w,EntityId site,long at,long rev)=>Orders(w).Where(q=>q.Input.Site==site&&Before(q,at,rev)).Select(q=>(q.At,q.Revision,Amount:-q.Rice)).Concat((w.PublicWorks?.Care??[]).Where(c=>c.Site==site&&(c.At<at||c.At==at&&c.Revision<rev)).Select(c=>(c.At,c.Revision,Amount:-1L))).ToArray();
 internal static long CashNet(ContractWorld w,EntityId site,long at,long rev)=>-Orders(w).Where(q=>q.Input.Site==site&&Before(q,at,rev)).Sum(q=>q.Coins)-(w.PublicWorks?.Care??[]).LongCount(c=>c.Site==site&&(c.At<at||c.At==at&&c.Revision<rev))*2;
 public static BuiltShip[] Ships(ContractWorld w)=>Orders(w).Where(q=>q.Input.Kind is WorksKind.TradeShip or WorksKind.Warship&&q.Due<=w.ElapsedSeconds).Select(q=>new BuiltShip(new("ship:"+q.Input.Id.Value.Replace(':','/')),q.Owner,q.Input.Site,q.Input.Kind,q.Due,w.PublicWorks!.Care.Any(c=>c.Ship==new EntityId("ship:"+q.Input.Id.Value.Replace(':','/'))&&c.At<=w.ElapsedSeconds&&w.ElapsedSeconds<c.Until),w.PublicWorks!.Care.LongCount(c=>c.Ship==new EntityId("ship:"+q.Input.Id.Value.Replace(':','/'))))).ToArray();
 public static WorksOrder[] KnownProjects(ContractWorld w,EntityId viewer)=>Orders(w).Where(q=>q.Actor==viewer||SocialWorld.Site(w,viewer)==q.Input.Site&&RegionalDomains.Authority(w,viewer,q.Input.Site,w.ElapsedSeconds,w.CommitSequence+1)).ToArray();
 public static bool MayOrder(ContractWorld w,EntityId actor,EntityId site,WorksKind kind,long at,long rev)
 {using var _ccRev=ControlContext.At(rev);
     return HouseholdCourt.Specialist(w,actor,site,at,rev) switch
     {
         CourtRole.WorksMagistrate=>kind is WorksKind.Agriculture or WorksKind.RepairFields or WorksKind.Port or
             WorksKind.RepairCastle || CastleWorks.IsFort(kind),
         CourtRole.TownMagistrate=>kind is WorksKind.Commerce or WorksKind.Workshop or WorksKind.RepairTown,
         _=>RegionalDomains.Authority(w,actor,site,at,rev)
     };
 }
 static WorksOrder Make(ContractWorld w,WorksInput i,EntityId actor,long at,long rev,bool legacy=false){using var _ccRev=ControlContext.At(rev);Need(NewGameWork.Enabled(w)&&Enum.IsDefined(i.Kind)&&EntityId.IsValid(i.Id.Value)&&TransportWork.At(w,actor,i.Site,at,rev,true)&&MayOrder(w,actor,i.Site,i.Kind,at,rev),"現地の担当者と行政権限が必要です");CastleWorks.Check(w,i,at,rev);bool repair=i.Kind is WorksKind.RepairFields or WorksKind.RepairTown or WorksKind.RepairCastle;Need(!repair||RegionalWeather.Damage(w,i.Site,i.Kind,at,rev)>0,"その区分に復旧対象の被害がありません");var account=CommunityEconomy.AccountAt(w,i.Site,at,rev);Need(account.Hunger==0&&VillageConsultation.Cooperative(w,i.Site,at,rev),"食糧不足か、村が労働協力を留保しています");int cap=Capacity(w,i.Site,i.Kind,account.Population);Need(Orders(w).Count(q=>q.Input.Site==i.Site&&q.Input.Kind==i.Kind&&q.Input.Section==i.Section&&q.Revision<rev)<cap&&!Orders(w).Any(q=>q.Input.Site==i.Site&&q.At<=at&&at<q.Due&&q.Revision<rev),"土地の上限か、既に進む普請を確認してください");bool ship=i.Kind is WorksKind.TradeShip or WorksKind.Warship;Need(!ship||Level(w,i.Site,WorksKind.Port,at,rev)>0,"港の整備が済んでから造船できます");long rice=ship?200:100,wood=ship?10:5,coins=ship?100:50;Need(legacy||StandingAdministration.WorkAllowed(w,actor,i.Site,coins,at,rev),"本人が引き受けた年度経費と収穫期の条件を確認してください");const int crew=20;Need(account.HouseRice-HouseSalary.Reserved(w,i.Site,at,rev)>=rice&&account.Workforce-account.Reserved>=crew&&MaterialMarkets.WoodAvailable(w,i.Site,at,rev)>=wood&&RegionalDomains.Cash(w,i.Site,at,rev)>=coins,"家の米・木材・銭と、ほかの用途に取られていない働き手を確認してください");return new(i,actor,RegionalDomains.Owner(w,i.Site)!.Value,at,rev,checked(at+(ship?14:7)*86400L),rice,wood,coins,crew,cap,"村代表が食料・人手・既存の約束を確認して協力。人手を工期中確保"){AuthorizationPolicy=legacy?null:StandingAdministration.Policy};}
 public static void Execute(ContractWorld w,WorksInput i,EntityId actor){var q=Make(w,i,actor,w.ElapsedSeconds,w.CommitSequence);w.PublicWorks??=new(1,Policy,[],[]);w.PublicWorks=w.PublicWorks with{Orders=[..Orders(w),q]};}
 internal static void Tick(ContractWorld w,bool autonomous){if(w.PublicWorks==null||!autonomous||w.ElapsedSeconds<86400)return;var acting=LiveTerritory.Acting(w);foreach(var site in (LiveTerritory.Enabled(w)?MaterialMarkets.Sites(w):Orders(w).Select(q=>q.Input.Site).Distinct())){var head=RegionalDomains.Head(w,site);if(head==null||!acting(head.Value)||StandingAdministration.KnownPolicy(w,head.Value,RegionalDomains.Owner(w,site)!.Value)==HousePolicy.Conserve||head==w.PlayerControl||Orders(w).Any(q=>q.Input.Site==site&&w.ElapsedSeconds<q.Due)||SocialWorld.Site(w,head.Value)!=site)continue;var id=new EntityId("request:npc-works/"+site.Value.Replace(':','/')+"/"+w.ElapsedSeconds/86400);if(SiegeFleet.PrepareNavalDefense(w,head.Value,site,id))continue;var priority=StandingAdministration.KnownPolicy(w,head.Value,RegionalDomains.Owner(w,site)!.Value);if(CastleWorks.Enabled(w)&&priority==HousePolicy.Military&&TransactionalWorld.TryApply(w,c=>Execute(c,new(id,site,WorksKind.Gatehouse){Section=CastleSection.Gate},head.Value)))continue;var preferred=priority==HousePolicy.Military?WorksKind.Workshop:priority==HousePolicy.Commerce?WorksKind.Commerce:WorksKind.Agriculture;var choices=LiveTerritory.Enabled(w)?new[]{WorksKind.RepairFields,WorksKind.RepairTown,WorksKind.RepairCastle,preferred,WorksKind.Workshop,WorksKind.Mine,WorksKind.Port,WorksKind.Commerce,WorksKind.Pasture}:new[]{WorksKind.Agriculture};foreach(var kind in choices.Distinct())if(TransactionalWorld.TryApply(w,c=>Execute(c,new(id,site,kind),head.Value)))break;}}
 internal static long? NextBoundary(ContractWorld w,long target)=>Orders(w).Select(q=>q.Due).Concat((w.PublicWorks?.Care??[]).Select(c=>c.Until)).Where(t=>t>w.ElapsedSeconds&&t<=target).Order().Select(t=>(long?)t).FirstOrDefault();
 public static void CareForShip(ContractWorld w,EntityId id,EntityId ship,EntityId actor){var built=Ships(w).Single(s=>s.Id==ship);var at=w.ElapsedSeconds;var rev=w.CommitSequence;Need(!built.Maintained&&RegionalDomains.Owner(w,built.Port)==built.Owner&&RegionalDomains.Authority(w,actor,built.Port,at,rev)&&TransportWork.At(w,actor,built.Port,at,rev,true),"現地の所有者・船・保守期間を確認してください");Need(RegionalDomains.Cash(w,built.Port,at,rev)>=2&&CommunityEconomy.AccountAt(w,built.Port,at,rev).HouseRice-HouseSalary.Reserved(w,built.Port,at,rev)>=1,"保守の銭2文と米1kgが不足しています");w.PublicWorks=w.PublicWorks! with{Care=[..w.PublicWorks!.Care,new(id,ship,built.Port,actor,at,at+30*86400L,rev)]};}
 public static void Validate(ContractWorld w,ContractWorld? prior){if(w.PublicWorks==null){Need(prior?.PublicWorks==null,"普請の原本が消えています");return;}Need(NewGameWork.Enabled(w)&&w.PublicWorks.Schema==1&&w.PublicWorks.Policy==Policy&&(Orders(w).Length>0||LiveTerritory.Enabled(w)),"普請の形式が不正です");if(prior?.PublicWorks!=null)Need(ContractJson.CanonicalHash(Orders(w).Take(prior.PublicWorks.Orders.Length).ToArray())==ContractJson.CanonicalHash(prior.PublicWorks.Orders),"過去の普請が改変されています");long rev=0,at=0;var ids=new HashSet<EntityId>();foreach(var q in Orders(w)){Need(q.Revision>rev&&q.Revision<=w.CommitSequence&&q.At>=at&&q.At<=w.ElapsedSeconds&&ids.Add(q.Input.Id),"普請の順序が不正です");var prefix=w.ForkTransportLocation();prefix.PublicWorks=w.PublicWorks with{Orders=Orders(w).Where(p=>p.Revision<q.Revision).ToArray()};Need(q.AuthorizationPolicy is null or StandingAdministration.Policy&&q==Make(prefix,q.Input,q.Actor,q.At,q.Revision,q.AuthorizationPolicy==null),"当時の資源・土地・協力と普請条件が違います");rev=q.Revision;at=q.At;}
 var care=w.PublicWorks.Care;Need(care.Select(c=>c.Id).Distinct().Count()==care.Length,"船の二重保守です");if(prior?.PublicWorks!=null)Need(care.Take(prior.PublicWorks.Care.Length).SequenceEqual(prior.PublicWorks.Care),"過去の保守を変えています");foreach(var c in care){Need(c.Revision>0&&c.Revision<=w.CommitSequence&&c.At<=w.ElapsedSeconds&&c.Until==c.At+30*86400L&&EntityId.IsValid(c.Id.Value)&&!Orders(w).Any(q=>q.Input.Id==c.Id),"保守期間・原本が不正です");var ship=Ships(w).Single(s=>s.Id==c.Ship);Need(ship.BuiltAt<=c.At&&ship.Port==c.Site&&RegionalDomains.Owner(w,c.Site)==ship.Owner&&RegionalDomains.Authority(w,c.Actor,c.Site,c.At,c.Revision)&&TransportWork.At(w,c.Actor,c.Site,c.At,c.Revision,true)&&!care.Any(other=>other.Ship==c.Ship&&other.Revision<c.Revision&&other.Until>c.At)&&RegionalDomains.Cash(w,c.Site,c.At,c.Revision)>=2&&CommunityEconomy.AccountAt(w,c.Site,c.At,c.Revision).HouseRice-HouseSalary.Reserved(w,c.Site,c.At,c.Revision)>=1,"当時の保守権限・資源が一致しません");}}

}
public sealed partial class WorldSession
{
 public CommandResult MaintainPublicShip(EntityId id,EntityId ship,long revision){using var _ccRev=ControlContext.At(revision);lock(gate){var old=state.PublicWorks?.Care.SingleOrDefault(c=>c.Id==id);if(old!=null)return new(old.Ship==ship?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,id,state.CommitSequence,"受付済みです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,id,state.CommitSequence,"表示を更新してください");if(!EntityId.IsValid(id.Value)||NewGameWork.OwnIdUsed(state,id)||state.Requests.Any(q=>q.Id==id))return new(ResultCode.IdPayloadConflict,id,state.CommitSequence,"原本IDを確認してください");try{Change(w=>PublicWorks.CareForShip(w,id,ship,w.PlayerControl));return new(ResultCode.Accepted,id,state.CommitSequence,"30日分の銭と米を保守へ実支出しました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,id,state.CommitSequence,e.Message);}}}
 public CommandResult StartPublicWork(WorksInput i,long revision){using var _ccRev=ControlContext.At(revision);lock(gate){var old=PublicWorks.Orders(state).SingleOrDefault(q=>q.Input.Id==i.Id);if(old!=null)return new(old.Input==i?ResultCode.AlreadyAccepted:ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"この普請は引受済みです");if(revision!=state.CommitSequence)return new(ResultCode.StateChanged,i.Id,state.CommitSequence,"表示を更新してください");if(NewGameWork.OwnIdUsed(state,i.Id)||state.Requests.Any(q=>q.Id==i.Id))return new(ResultCode.IdPayloadConflict,i.Id,state.CommitSequence,"使用済みの原本です");try{Change(w=>PublicWorks.Execute(w,i,w.PlayerControl));return new(ResultCode.Accepted,i.Id,state.CommitSequence,"人手と資材を確保して普請を始めました");}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or ArgumentException or OverflowException){return new(ResultCode.NotAvailable,i.Id,state.CommitSequence,e.Message);}}}
}
